args.sql:
SELECT COUNT(*) FROM households WHERE residentcount > 0 AND housenum IN (
    SELECT p.houselink FROM properties p 
    WHERE CAST(p.dwelling_specs->>'Bath_Count' AS numeric) / (
        SELECT h.residentcount FROM households h WHERE h.housenum = p.houselink
    ) > 0.5
);

SELECT ROUND(AVG(CAST(p.dwelling_specs->>'Bath_Count' AS numeric) / h.residentcount), 2)
FROM households h
JOIN properties p ON p.houselink = h.housenum;

SELECT ARRAY_AGG(h.housenum ORDER BY CAST(p.dwelling_specs->>'Bath_Count' AS numeric) / h.residentcount DESC)
FROM households h
JOIN properties p ON p.houselink = h.housenum;
